	}
	ret := C.av_channel_layout_compare(l.c, l2.c)
	if err := newError(ret); err != nil {
		return false, err
	}
	return ret == 0, nil
}

func (l ChannelLayout) Equal(l2 ChannelLayout) bool {
	v, _ := l.Compare(l2)
	return v
}

