	if *output == "" || len(inputs) == 0 {
		log.Println("使用方法: go run . -o <输出文件> <输入文件1> <输入文件2> ...")
		return
	}

	if err := concatenate(inputs, *output); err != nil {
		log.Fatalf("拼接过程中发生错误: %v", err)
